import { button, badge, emptyState, escapeHtml as e, statusBadge } from "./ui.js";
import { icon } from "./icons.js";
import { panel, metric, table, select } from "./chairman.js";
import { statuses } from "./data.js";
import { followupStatuses } from "./vice-data.js";
import { networkTelemetry } from "./network-fleet.js";
import { coordinatorViews, coordinatorScope, coordinatorBuses, coordinatorFleet, coordinatorDrivers, coordinatorStudents, coordinatorRoutes, coordinatorTasks, coordinatorOverview, coordinatorReportTypes, allocationStatuses, driverStatuses, visibleCoordinatorReports } from "./coordinator-data.js";

const choices=(values,current)=>values.map(([id,name])=>`<option value="${e(id)}" ${String(id)===String(current)?"selected":""}>${e(name)}</option>`).join("");
const heading=(title,text,actions="")=>`<header class="chairman-page-heading"><div><h1>${title}</h1><p>${text}</p></div><div class="chairman-heading-actions">${badge("Demo transport", "amber")}${actions}</div></header>`;
const footer=(label)=>`<p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel","close-dialog",{variant:"secondary"})}<button class="button primary" type="submit">${label}</button></footer>`;
function identity(options,scope){
  const entries=options.state.accounts.flatMap((person)=>person.grants.map((grant,index)=>({person,grant,index}))).filter(({grant})=>grant.role==="transport"),current=options.context.account.id+"|"+options.context.account.grants.indexOf(options.context.grant);
  return `<header class="section-identity"><div><span class="chairman-eyebrow">TRANSPORT COORDINATOR</span><h1>${e(scope.branch.school)}</h1><p>School fleet, route readiness and transport coordination</p></div><label class="principal-demo-account"><span>Demo Transport Coordinator</span><span class="select-wrap"><select data-change="account" aria-label="Preview Transport Coordinator">${choices(entries.map(({person,grant,index})=>[person.id+"|"+index,person.name+" · "+options.state.branches.find((branch)=>branch.id===grant.branch)?.name]),current)}</select>${icon("chevronDown",14)}</span></label></header>`;
}
function filters(options,kind){
  const f=options.transportCoordinator,buses=coordinatorBuses(options.state,options.context);
  return `<div class="chairman-filters coordinator-filters">${select("Bus / route","coordinator-bus-filter",[["all","All school buses"],...buses.map((bus)=>[bus.id,"Bus "+bus.id+" · "+bus.name])],f.busFilter)}${["routes","fleet","brief"].includes(kind)?select("Vehicle status","coordinator-status",[["all","All statuses"],...Object.entries(statuses).map(([id,status])=>[id,status.label])],f.status):""}${kind==="students"?select("Student allocation","coordinator-allocation",Object.entries(allocationStatuses),f.allocation):""}${kind==="drivers"?select("Driver assignment","coordinator-driver-status",Object.entries(driverStatuses),f.driverStatus):""}${kind==="tasks"?select("Issue progress","coordinator-task-status",[["all","All assigned tasks"],...Object.entries(followupStatuses)],f.taskStatus):""}${kind!=="brief"?`<label class="chairman-search">${icon("search",16)}<input type="search" aria-label="Search transport records" data-change="coordinator-query" data-focus="coordinator-search" value="${e(f.query)}" placeholder="${kind==="students"?"Student, admission or class":kind==="drivers"?"Driver, bus or route":kind==="tasks"?"Issue title or bus":"Bus, route, driver or stop"}"></label>`:""}</div>`;
}
function busDetail(options,bus){
  const t=networkTelemetry(bus,{progress:options.progress,paused:options.paused,elapsed:options.networkElapsed}),students=coordinatorStudents(options.state,options.context,{busFilter:bus.id});
  return `<section class="surface coordinator-bus-detail" data-coordinator-telemetry="${e(bus.id)}"><header><div><span class="chairman-eyebrow">SELECTED VEHICLE</span><h2 tabindex="-1" id="coordinator-bus-title">Bus ${e(bus.id)} · ${e(bus.name)}</h2><p>${e(bus.registration)} · ${e(bus.driver||"Unassigned")}</p></div>${statusBadge(bus.status)}</header><div class="coordinator-telemetry"><div><span>Assigned students</span><strong>${students.length}</strong></div><div><span>Demo arrival</span><strong data-coordinator-value="eta">${bus.status==="school"?"Arrived":t.eta+" min"}</strong></div><div><span>Simulated speed</span><strong><span data-coordinator-value="speed">${t.speed}</span> <small>km/h</small></strong></div><div><span>Simulated signal</span><strong data-coordinator-value="updated">${e(t.updated)}</strong></div></div><div class="coordinator-next-stop"><span>${bus.status==="school"?"Arrived at":"Demo next stop"}</span><strong data-coordinator-value="nextStop">${e(t.nextStop)}</strong><progress data-coordinator-value="progress" value="${t.progress}" max="1" aria-label="Selected bus simulated trip progress"></progress></div><div class="section-row-actions">${button("Manage route & assignments","edit-bus",{value:bus.id,variant:"secondary compact",iconName:"edit"})}${button("Record transport issue","coordinator-task-new",{value:bus.id,variant:"secondary compact",iconName:"alert"})}</div><p class="chairman-filter-note">Locations, speed, arrival and signal are simulated. Assigned-student counts come from school records.</p></section>`;
}
function fleet(options,scope){
  const f=options.transportCoordinator,data=coordinatorOverview(options.state,options.context),buses=coordinatorFleet(options.state,options.context).filter((bus)=>f.status==="all"||bus.status===f.status),current=buses.find((bus)=>bus.id===f.busId);
  return heading("Fleet Activity","Follow your school’s buses, routes and transport readiness.")+`<section class="surface coordinator-map-card"><div class="coordinator-map-heading"><div><h2>${e(scope.branch.name)} fleet map</h2><p>Street map · Illustrative pickup paths · ${buses.length} matching buses</p></div>${button(options.paused?"Resume":"Pause","pause",{variant:"secondary compact",iconName:options.paused?"play":"pause"})}</div><div class="coordinator-fleet-filters">${select("Map vehicle status","coordinator-status",[["all","All school buses"],...Object.entries(statuses).map(([id,status])=>[id,status.label])],f.status)}${button("Show school routes","coordinator-map-reset",{variant:"secondary compact",iconName:"locate"})}${badge(options.paused?"Paused":"Live simulation",options.paused?"neutral":"green")}</div><div id="coordinator-fleet-map" class="school-network-map" role="region" aria-label="Assigned school fleet street map"></div></section><div class="chairman-metrics">${metric("School buses",data.buses.length,"Editable operational demo fleet","bus")}${metric("On route",data.route,"Saved demonstration trip status","route")}${metric("Signal delayed",data.delayed,"Simulated GPS signal status","alert","amber")}${metric("Students allocated",data.allocated,"Actual student transport assignments","users","blue")}</div><p class="coordinator-readiness">${data.unassigned} buses need a driver · ${data.tasks.filter((task)=>task.status!=="resolved").length} assigned issues open</p><div class="coordinator-fleet-lower"><section class="surface coordinator-fleet-list"><header class="chairman-panel-heading"><div><h2>School vehicles</h2><p>Select a vehicle or its map marker</p></div></header>${buses.map((bus)=>`<button type="button" class="coordinator-bus-row ${current?.id===bus.id?"is-selected":""}" aria-pressed="${current?.id===bus.id}" data-action="coordinator-bus" data-value="${e(bus.id)}"><span class="fleet-bus-icon" style="--route-color:${e(bus.color)}">${icon("bus",20)}</span><span><strong>Bus ${e(bus.id)} · ${e(bus.name)}</strong><small>${e(bus.driver||"Unassigned")}</small></span>${statusBadge(bus.status)}</button>`).join("")||emptyState("bus","No matching vehicles","Choose another status. New schools do not borrow illustrative network buses.")}</section>${current?busDetail(options,current):`<section class="surface">${emptyState("bus","No selected vehicle","Your school’s operational buses will appear here.")}</section>`}</div>`;
}
function routes(options){
  const buses=coordinatorRoutes(options.state,options.context,options.transportCoordinator);
  return heading("Routes & Stops","Review pickup sequences and keep route names, stops and assignments current.")+filters(options,"routes")+`<div class="coordinator-route-grid">${buses.map((bus)=>`<article class="surface coordinator-route-card"><header><div><span class="chairman-eyebrow">BUS ${e(bus.id)}</span><h2>${e(bus.name)}</h2><p>${e(bus.registration)} · ${e(bus.driver||"Unassigned")}</p></div>${statusBadge(bus.status)}</header><ol>${bus.stops.map((stop,index)=>`<li><span>${icon(index===bus.stops.length-1?"school":"pin",17)}</span><div><strong>${e(stop)}</strong><small>${index===bus.stops.length-1?"School destination":"Pickup stop "+(index+1)}</small></div></li>`).join("")}</ol><footer>${button("Manage route & assignments","edit-bus",{value:bus.id,variant:"secondary",iconName:"edit"})}<span>${coordinatorStudents(options.state,options.context,{busFilter:bus.id}).length} assigned students</span></footer></article>`).join("")||`<section class="surface">${emptyState("route","No matching routes","Try another school bus or search.")}</section>`}</div><p class="chairman-filter-note">Stop labels are editable in travel order. The final school destination is fixed; illustrated map paths remain unchanged.</p>`;
}
function assignments(options){
  const f=options.transportCoordinator,studentTab=f.peopleTab==="students",students=coordinatorStudents(options.state,options.context,f),drivers=coordinatorDrivers(options.state,options.context,f),buses=coordinatorBuses(options.state,options.context),page=Math.min(f.page,Math.max(1,Math.ceil(students.length/12))),start=(page-1)*12;
  return heading("Drivers & Students","Allocate existing school drivers and student records to the operational fleet.")+`<div class="chairman-segmented coordinator-people-tabs" role="group" aria-label="Transport assignment views">${button("Student allocations","coordinator-people-tab",{value:"students",variant:studentTab?"primary compact":"secondary compact",extra:`aria-pressed="${studentTab}"`})}${button("Driver assignments","coordinator-people-tab",{value:"drivers",variant:!studentTab?"primary compact":"secondary compact",extra:`aria-pressed="${!studentTab}"`})}</div>`+filters(options,studentTab?"students":"drivers")+panel(studentTab?"Student transport allocations":"School driver assignments",studentTab?"Name, admission, class and bus allocation · Admission and guardian records stay read-only":"A driver serves one bus at a time. Unassigned Driver appointments remain available for allocation.",studentTab?(students.length?table(["Student","Class","Assigned bus / route","Driver","Action"],students.slice(start,start+12).map((row)=>`<tr><td><strong>${e(row.student.name)}</strong><small>${e(row.student.admissionNumber)}</small></td><td>Class ${e(row.student.className)}</td><td>${row.bus?`Bus ${e(row.bus.id)}<small>${e(row.bus.name)}</small>`:badge("No bus assigned","amber")}</td><td>${e(row.bus?.driver||"—")}</td><td>${row.bus?button("Manage allocation","edit-bus",{value:row.bus.id,variant:"secondary compact"}):buses.length?button("Assign to a bus","coordinator-allocate",{value:row.student.id,variant:"secondary compact"}):"No school fleet"}</td></tr>`).join(""),"Student transport allocations")+`<div class="chairman-pager"><span>${start+1}–${Math.min(start+12,students.length)} of ${students.length}</span><div>${button("Previous","coordinator-page",{value:page-1,variant:"secondary compact",extra:page<=1?"disabled":""})}<span>Page ${page}</span>${button("Next","coordinator-page",{value:page+1,variant:"secondary compact",extra:start+12>=students.length?"disabled":""})}</div></div>`:emptyState("users","No matching student allocations","Try another bus, allocation status or search.")):(drivers.length?table(["School driver","Assigned vehicle","Route status","Action"],drivers.map((row)=>`<tr><td><strong>${e(row.person.name)}</strong></td><td>${row.buses.map((bus)=>`Bus ${e(bus.id)}<small>${e(bus.registration)} · ${e(bus.name)}</small>`).join("")||badge("Awaiting assignment","amber")}</td><td>${row.buses.map((bus)=>statusBadge(bus.status)).join("")||"—"}</td><td>${row.buses.length?button("Manage bus assignment","edit-bus",{value:row.buses[0].id,variant:"secondary compact"}):buses.length?button("Assign driver to bus","coordinator-driver-allocate",{value:row.person.id,variant:"secondary compact"}):"No school fleet"}</td></tr>`).join(""),"School driver assignments"):emptyState("users","No matching driver appointments","The Principal or Chairman appoints Driver accounts for this school.")));
}
function issues(options){
  const tasks=coordinatorTasks(options.state,options.context,options.transportCoordinator),buses=coordinatorBuses(options.state,options.context);
  return heading("Issues & Coordination","Track transport follow-ups assigned to you and share progress with the Vice Principal.",buses.length?button("Record transport issue","coordinator-task-new",{value:"",iconName:"plus"}):"")+filters(options,"tasks")+panel("Your transport follow-ups","New issues are assigned to you and appear on the Vice Principal’s Follow-up board. Progress updates share the same note history.",tasks.length?`<div class="grade-support-grid">${tasks.map((task)=>`<article class="grade-support-card"><div>${badge(task.busId?"Bus "+task.busId:"School transport","blue")}${badge(followupStatuses[task.status],task.status==="resolved"?"green":"amber")}</div><h3>${e(task.title)}</h3><small>Due ${e(task.due)} · ${e(options.context.account.name)}</small><p>${e(task.notes[0]?.text)}</p>${button("Update issue progress","coordinator-task-edit",{value:task.id,variant:"secondary compact"})}</article>`).join("")}</div>`:emptyState("checkCircle","No matching assigned issues","Record a bus concern or review another task status."))+`<p class="chairman-filter-note">The Vice Principal controls task owners, category and due dates. Recording or resolving an issue does not alter GPS signals, dispatch a bus or send a notification.</p>`;
}
export function coordinatorReportPreview(report){
  const c=report.criteria;
  return `<article class="coordinator-report-preview section-report-preview"><div class="coordinator-report-brand"><strong>Sussex College Network</strong>${badge("SAMPLE · PROTOTYPE","amber")}</div><h2>${e(report.title)}</h2><p>${e(report.owner.school)} · Transport Coordinator: ${e(report.owner.by)}</p><p>Snapshot: ${e(c.to)} · Bus: ${e(c.busFilter==="all"?"All school buses":c.busFilter)} · ${e(c.status==="all"?"All statuses":statuses[c.status].label)}</p>${report.type!=="brief"?`<p>Search: ${e(c.query||"All records")}${report.type==="students"?" · "+e(allocationStatuses[c.allocation]):report.type==="tasks"?" · "+e(c.taskStatus==="all"?"All assigned tasks":followupStatuses[c.taskStatus]):""}</p>`:""}<div class="section-summary-strip"><div><span>Operational buses in snapshot</span><strong>${report.summary.buses}</strong></div><div><span>Report rows</span><strong>${report.summary.rows}</strong></div>${["brief","students"].includes(report.type)?`<div><span>Student records</span><strong>${report.summary.students}</strong></div>`:""}</div>${table(report.customColumns.map(([,label])=>label),report.customRows.map((row)=>`<tr>${report.customColumns.map(([key])=>`<td>${e(row[key]??"—")}</td>`).join("")}</tr>`).join(""),"Transport report data")}<p class="chairman-filter-note">Locations, signal, progress and arrival estimates are simulated at capture time. Vehicle assignments and student allocations use saved school records. Free-text issue notes and guardian credentials are excluded.</p></article>`;
}
export function coordinatorReportHTML(report,logo=""){
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(report.title)} · Sussex College Network</title><style>body{font:14px Arial,sans-serif;color:#183a32;max-width:1120px;margin:36px auto;padding:0 24px}img{width:66px;float:right}h2{font-size:27px}table{width:100%;border-collapse:collapse;margin:24px 0}td,th{text-align:left;border-bottom:1px solid #dce6e1;padding:10px}th{background:#edf4f0}.table-scroll{overflow:auto}.section-summary-strip{display:flex;gap:40px;background:#edf4f0;padding:20px}.section-summary-strip span{display:block;font-size:12px}.section-summary-strip strong{font-size:22px}.chairman-filter-note{color:#52685f;font-size:12px}.badge{display:inline-block;margin:8px;color:#825414}@media print{body{margin:0;max-width:none}tr{break-inside:avoid}thead{display:table-header-group}}@page{size:A4 landscape;margin:14mm}</style></head><body>${logo?`<img alt="Sussex College Network logo" src="${e(logo)}">`:""}${coordinatorReportPreview(report)}<footer>School Transport Coordination · Generated ${e(report.generatedAt)}</footer></body></html>`;
}
function reports(options,scope){
  const f=options.transportCoordinator,reports=visibleCoordinatorReports(options.state,options.context),current=reports.find((report)=>report.id===f.reportId);
  return heading("Transport Reports","Capture fleet readiness, routes, allocations and your assigned coordination work.")+`<div class="section-report-builder surface"><div>${select("Report type","coordinator-report-type",Object.entries(coordinatorReportTypes),f.reportType)}</div>${filters(options,f.reportType)}<div class="section-report-generate"><p>${icon("school",17)}${e(scope.branch.name)} · Operational fleet only</p>${button("Generate transport report","coordinator-generate-report",{iconName:"file"})}</div></div><section class="surface chairman-report-result"><div class="chairman-report-actions">${current?select("Download format","coordinator-report-format",[["csv","CSV spreadsheet"],["html","Standalone HTML"]],f.reportFormat)+button("Download report","coordinator-download-report",{value:current.id,variant:"secondary",iconName:"download"})+button("Print / Save PDF","coordinator-print-report",{value:current.id,variant:"secondary",iconName:"file"}):"Report preview"}</div>${current?coordinatorReportPreview(current):emptyState("file","Your transport report starts here","Choose a report and scope, then generate a snapshot.")}</section>`+panel("Saved coordination snapshots","Latest eight per coordinator and school · Report access follows current school and task ownership",`<div class="chairman-report-history">${reports.map((item)=>`<button type="button" class="chairman-history-card ${current?.id===item.id?"is-selected":""}" data-action="coordinator-open-report" data-value="${item.id}">${icon("file",20)}<span><strong>${e(item.title)}</strong><small>${e(item.criteria.to)} · ${item.customRows.length} rows</small></span>${badge("Sample","neutral")}</button>`).join("")||'<p class="chairman-no-history">Generated transport reports will appear here.</p>'}</div>`);
}
export function transportCoordinatorPage(options){
  const scope=coordinatorScope(options.state,options.context);if(!scope)return emptyState("bus","No transport appointment","An active Transport Coordinator school appointment is required.");
  const view=options.transportCoordinator.view;
  return `<section class="chairman-portal section-portal transport-coordinator-portal">${identity(options,scope)}<nav class="chairman-view-bar section-view-bar" aria-label="Transport Coordinator views">${coordinatorViews.map((item)=>`<a href="#transport/overview/${item.id}" aria-label="${item.name}" ${item.id===view?'aria-current="page" class="is-active"':""}>${icon(item.icon,18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>`).join("")}</nav><div class="chairman-analytics section-analytics">${({fleet,routes,assignments,issues,reports})[view](options,scope)}</div></section>`;
}
export function coordinatorTaskForm(options,previous=null,busId=""){
  const buses=coordinatorBuses(options.state,options.context);
  return `<form data-form="coordinator-task"><div class="form-body"><input type="hidden" name="id" value="${e(previous?.id||"")}">${previous?`<h3>${e(previous.title)}</h3><p class="chairman-filter-note">${previous.busId?"Bus "+e(previous.busId):"School transport"} · Due ${e(previous.due)}</p>`:`<label class="field">School bus<select name="busId" required>${choices(buses.map((bus)=>[bus.id,"Bus "+bus.id+" · "+bus.name]),busId)}</select></label><label class="field">Issue title<input name="title" maxlength="140" required></label><label class="field">Follow-up due<input name="due" type="date" min="2026-11-20" max="2026-11-27" value="2026-11-23" required></label>`}<label class="field">Issue progress<select name="status">${choices(Object.entries(followupStatuses),previous?.status||"open")}</select></label><label class="field">Update for Vice Principal<textarea name="note" rows="4" maxlength="1200" required></textarea></label>${previous?`<div class="vice-note-history"><h3>Coordination history</h3>${previous.notes.map((note)=>`<article><p>${e(note.text)}</p><small>${e(note.by)} · ${e(note.at.slice(0,10))}</small></article>`).join("")}</div>`:""}<p class="chairman-filter-note">Saved to the same school Follow-up board. The Vice Principal can review or reassign it; no message is sent.</p></div>${footer(previous?"Save issue progress":"Record transport issue")}</form>`;
}
export function coordinatorAllocationForm(options,value,kind){
  const buses=coordinatorBuses(options.state,options.context),person=kind==="student"?coordinatorStudents(options.state,options.context).find((row)=>row.student.id===value)?.student:coordinatorDrivers(options.state,options.context).find((row)=>row.person.id===value)?.person;
  return `<form data-form="coordinator-allocation"><div class="form-body"><input type="hidden" name="person" value="${e(value)}"><input type="hidden" name="kind" value="${kind}"><h3>${e(person.name)}</h3><label class="field">Assign to school bus<select name="busId" required>${choices(buses.map((bus)=>[bus.id,"Bus "+bus.id+" · "+bus.name]),"")}</select></label><p class="chairman-filter-note">${kind==="student"?"The student’s admission and class records stay unchanged.":"A driver serves one vehicle at a time. Their former bus will be left without a driver."}</p></div>${footer("Save transport allocation")}</form>`;
}
export function updateCoordinatorTelemetry(root,fleet,progress,paused,elapsed){
  const detail=root.querySelector("[data-coordinator-telemetry]");if(!detail)return;
  const bus=fleet.find((bus)=>bus.id===detail.dataset.coordinatorTelemetry);if(!bus)return;
  const telemetry=networkTelemetry(bus,{progress,paused,elapsed});
  for(const node of detail.querySelectorAll("[data-coordinator-value]")){const key=node.dataset.coordinatorValue;if(key==="progress")node.value=telemetry.progress;else if(key==="eta")node.textContent=bus.status==="school"?"Arrived":telemetry.eta+" min";else node.textContent=telemetry[key];}
}
